CREATE TABLE IF NOT EXISTS "clm_contract_type" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) NOT NULL,
    "name" varchar(128) NOT NULL,
    "description" varchar(512) DEFAULT '',
    "status" tinyint NOT NULL DEFAULT 0,
    "sort" int NOT NULL DEFAULT 0,
    "current_version_id" bigint DEFAULT NULL,
    "template_file_key" varchar(255) DEFAULT NULL,
    "template_file_name" varchar(255) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 合同类型';

CREATE TABLE IF NOT EXISTS "clm_contract_type_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "type_id" bigint NOT NULL,
    "version_no" int NOT NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "form_conf" text,
    "form_fields" text,
    "process_definition_key" varchar(64) NOT NULL DEFAULT 'clm_contract_approval_v1',
    "remark" varchar(255) DEFAULT '',
    "published_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 合同类型版本';

CREATE TABLE IF NOT EXISTS "clm_party" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "party_type" tinyint NOT NULL DEFAULT 1,
    "name" varchar(255) NOT NULL,
    "short_name" varchar(64) DEFAULT NULL,
    "unified_credit_code" varchar(64) DEFAULT '',
    "internal_flag" bit NOT NULL DEFAULT FALSE,
    "contact_name" varchar(64) DEFAULT '',
    "contact_phone" varchar(32) DEFAULT '',
    "address" varchar(512) DEFAULT '',
    "status" tinyint NOT NULL DEFAULT 0,
    "remark" varchar(255) DEFAULT '',
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 签约方';

CREATE TABLE IF NOT EXISTS "clm_contract" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_no" varchar(64) DEFAULT NULL,
    "title" varchar(255) NOT NULL,
    "type_id" bigint NOT NULL,
    "type_version_id" bigint NOT NULL,
    "owner_user_id" bigint NOT NULL,
    "owner_dept_id" bigint DEFAULT NULL,
    "amount" decimal(18,2) DEFAULT NULL,
    "currency" varchar(8) NOT NULL DEFAULT 'CNY',
    "sign_date" date DEFAULT NULL,
    "effective_date" date DEFAULT NULL,
    "expiry_date" date DEFAULT NULL,
    "custom_data" text,
    "description" text,
    "lifecycle_status" tinyint NOT NULL DEFAULT 1,
    "approval_status" tinyint NOT NULL DEFAULT 0,
    "current_document_version_id" bigint DEFAULT NULL,
    "current_binding_id" bigint DEFAULT NULL,
    "current_revision_id" bigint DEFAULT NULL,
    "source_mode" varchar(32) NOT NULL DEFAULT 'MANUAL',
    "stage_code" varchar(32) NOT NULL DEFAULT 'DRAFT',
    "no_commitment_confirmed" bit NOT NULL DEFAULT FALSE,
    "numbering_rule_version_id" bigint DEFAULT NULL,
    "source_contract_id" bigint DEFAULT NULL,
    "relation_type" varchar(32) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 合同';

CREATE TABLE IF NOT EXISTS "clm_contract_party" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL,
    "party_id" bigint NOT NULL,
    "role_code" varchar(32) NOT NULL,
    "sort" int NOT NULL DEFAULT 0,
    "party_snapshot" text,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 合同签约方';

CREATE TABLE IF NOT EXISTS "clm_document" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL,
    "role_code" varchar(32) NOT NULL DEFAULT 'MAIN',
    "name" varchar(255) NOT NULL,
    "current_version_id" bigint DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 合同文档';

CREATE TABLE IF NOT EXISTS "clm_document_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "document_id" bigint NOT NULL,
    "contract_id" bigint NOT NULL,
    "version_no" int NOT NULL,
    "parent_version_id" bigint DEFAULT NULL,
    "file_key" varchar(255) NOT NULL,
    "file_name" varchar(255) NOT NULL,
    "mime_type" varchar(128) DEFAULT '',
    "file_size" bigint NOT NULL DEFAULT 0,
    "checksum_sha256" char(64) NOT NULL,
    "source_type" varchar(32) NOT NULL DEFAULT 'UPLOAD',
    "frozen" bit NOT NULL DEFAULT FALSE,
    "remark" varchar(255) DEFAULT '',
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 文档版本';

CREATE TABLE IF NOT EXISTS "clm_document_blob" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "sha256" char(64) NOT NULL,
    "size" bigint NOT NULL,
    "content" longblob NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 文档内容';

CREATE TABLE IF NOT EXISTS "clm_workflow_binding" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL,
    "purpose" varchar(32) NOT NULL DEFAULT 'APPROVAL',
    "process_definition_key" varchar(64) NOT NULL,
    "process_definition_id" varchar(64) DEFAULT '',
    "process_instance_id" varchar(64) DEFAULT NULL,
    "document_version_id" bigint NOT NULL,
    "contract_type_version_id" bigint NOT NULL,
    "submitted_revision_id" bigint DEFAULT NULL,
    "current_revision_id" bigint DEFAULT NULL,
    "approved_revision_id" bigint DEFAULT NULL,
    "route_version_id" bigint DEFAULT NULL,
    "submit_request_id" varchar(64) DEFAULT NULL,
    "supersedes_case_id" bigint DEFAULT NULL,
    "cancel_reason" varchar(512) DEFAULT NULL,
    "form_snapshot" text,
    "checksum_sha256" char(64) NOT NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "result_reason" varchar(512) DEFAULT '',
    "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 流程绑定';

CREATE TABLE IF NOT EXISTS "clm_contract_participant" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL,
    "principal_type" varchar(16) NOT NULL DEFAULT 'USER',
    "principal_id" bigint NOT NULL,
    "role_code" varchar(32) NOT NULL,
    "can_view" bit NOT NULL DEFAULT TRUE,
    "can_edit" bit NOT NULL DEFAULT FALSE,
    "can_download" bit NOT NULL DEFAULT FALSE,
    "can_manage" bit NOT NULL DEFAULT FALSE,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 合同参与人';

CREATE TABLE IF NOT EXISTS "clm_audit_event" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "aggregate_type" varchar(32) NOT NULL,
    "aggregate_id" bigint NOT NULL,
    "contract_id" bigint DEFAULT NULL,
    "action" varchar(64) NOT NULL,
    "actor_user_id" bigint DEFAULT NULL,
    "actor_name" varchar(64) DEFAULT '',
    "detail_json" text,
    "occurred_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CLM 审计事件';

CREATE TABLE IF NOT EXISTS "clm_template" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) NOT NULL, "name" varchar(128) NOT NULL, "contract_type_id" bigint NOT NULL,
    "current_version_id" bigint DEFAULT NULL, "status" tinyint NOT NULL DEFAULT 0, "description" varchar(512) DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_template_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "template_id" bigint NOT NULL, "version_no" int NOT NULL, "status" varchar(32) NOT NULL,
    "file_key" varchar(255) NOT NULL, "file_name" varchar(255) NOT NULL, "mime_type" varchar(128) DEFAULT '',
    "file_size" bigint NOT NULL DEFAULT 0, "checksum_sha256" char(64) DEFAULT NULL,
    "published_time" timestamp DEFAULT NULL, "remark" varchar(255) DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_contract_revision" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL, "revision_no" int NOT NULL, "base_revision_id" bigint DEFAULT NULL,
    "contract_type_version_id" bigint NOT NULL, "template_version_id" bigint DEFAULT NULL,
    "main_document_version_id" bigint DEFAULT NULL, "document_version_ids_json" text NOT NULL,
    "field_snapshot_json" text NOT NULL, "party_snapshot_json" text NOT NULL,
    "commitment_snapshot_json" text NOT NULL, "no_commitment" bit NOT NULL DEFAULT FALSE,
    "change_source" varchar(32) NOT NULL, "change_reason" varchar(512) DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"),
    CONSTRAINT "uk_clm_revision_no" UNIQUE ("tenant_id", "contract_id", "revision_no", "deleted")
);

CREATE TABLE IF NOT EXISTS "clm_commitment" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "contract_id" bigint NOT NULL,
    "category" varchar(64) NOT NULL, "content" varchar(2000) NOT NULL, "owner_user_id" bigint DEFAULT NULL,
    "due_date" date DEFAULT NULL, "risk_level" varchar(32) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_numbering_rule_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "rule_code" varchar(64) NOT NULL,
    "contract_type_id" bigint DEFAULT NULL, "version_no" int NOT NULL, "status" varchar(32) NOT NULL,
    "prefix" varchar(32) DEFAULT 'HT-', "include_party_short_name" bit NOT NULL DEFAULT TRUE,
    "date_pattern" varchar(32) DEFAULT 'yyyy', "separator" varchar(8) DEFAULT '-',
    "sequence_length" int NOT NULL DEFAULT 4, "reset_period" varchar(16) DEFAULT 'YEAR', "effective_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_number_sequence" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "rule_version_id" bigint NOT NULL,
    "period_key" varchar(16) NOT NULL, "current_value" bigint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"),
    CONSTRAINT "uk_clm_number_sequence" UNIQUE ("tenant_id", "rule_version_id", "period_key", "deleted")
);

CREATE TABLE IF NOT EXISTS "clm_routing_rule_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "rule_code" varchar(64) NOT NULL, "name" varchar(128) NOT NULL,
    "contract_type_id" bigint DEFAULT NULL, "version_no" int NOT NULL, "priority" int NOT NULL DEFAULT 100,
    "condition_json" text NOT NULL, "process_definition_key" varchar(64) NOT NULL,
    "status" varchar(32) NOT NULL, "effective_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_approval_task_revision_binding" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "task_id" varchar(64) NOT NULL,
    "approval_case_id" bigint NOT NULL, "contract_id" bigint NOT NULL, "decision_revision_id" bigint NOT NULL,
    "action" varchar(16) NOT NULL, "reason" varchar(512) DEFAULT '', "request_id" varchar(64) NOT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"),
    CONSTRAINT "uk_clm_approval_task" UNIQUE ("tenant_id", "task_id", "deleted")
);

CREATE TABLE IF NOT EXISTS "clm_collaboration_case" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL, "requested_revision_id" bigint NOT NULL,
    "completed_revision_id" bigint DEFAULT NULL, "initiator_user_id" bigint NOT NULL,
    "legal_user_id" bigint NOT NULL, "status" varchar(32) NOT NULL DEFAULT 'RUNNING',
    "reason" varchar(1000) DEFAULT '', "conclusion" varchar(2000) DEFAULT '',
    "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_collaboration_event" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "case_id" bigint NOT NULL, "contract_id" bigint NOT NULL, "revision_id" bigint DEFAULT NULL,
    "event_type" varchar(32) NOT NULL, "actor_user_id" bigint NOT NULL, "content" varchar(4000) DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_governance_issue" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "issue_type" varchar(64) NOT NULL, "status" varchar(32) NOT NULL DEFAULT 'OPEN',
    "contract_id" bigint DEFAULT NULL, "approval_binding_id" bigint DEFAULT NULL,
    "source_ref" varchar(255) DEFAULT '', "summary" varchar(1000) NOT NULL, "detail_json" text,
    "owner_user_id" bigint DEFAULT NULL, "resolved_by" bigint DEFAULT NULL, "resolved_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_reconciliation_run" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "run_key" varchar(128) NOT NULL, "trigger_type" varchar(32) NOT NULL DEFAULT 'MANUAL',
    "status" varchar(32) NOT NULL DEFAULT 'RUNNING', "scanned_count" int NOT NULL DEFAULT 0,
    "issue_count" int NOT NULL DEFAULT 0, "repaired_count" int NOT NULL DEFAULT 0,
    "report_json" text, "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_permission_policy_version" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "version_no" int NOT NULL, "status" varchar(32) NOT NULL DEFAULT 'DRAFT',
    "role_capabilities_json" text, "scope_limits_json" text, "node_edit_policy_json" text,
    "remark" varchar(500) DEFAULT '', "published_by" bigint DEFAULT NULL, "published_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_user_scope" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL, "role_code" varchar(64) NOT NULL,
    "org_scope_json" text, "type_scope_json" text, "policy_version_id" bigint NOT NULL,
    "effective_from" timestamp DEFAULT NULL, "effective_to" timestamp DEFAULT NULL,
    "status" varchar(32) NOT NULL DEFAULT 'ACTIVE',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_user_scope_item" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_scope_id" bigint NOT NULL, "scope_type" varchar(32) NOT NULL, "scope_id" bigint NOT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_saved_filter" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL, "scene_code" varchar(64) NOT NULL, "name" varchar(128) NOT NULL,
    "filter_json" text NOT NULL, "default_flag" bit NOT NULL DEFAULT FALSE,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_ai_review_run" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "contract_id" bigint NOT NULL, "revision_id" bigint NOT NULL, "run_type" varchar(32) NOT NULL,
    "provider_code" varchar(64) NOT NULL DEFAULT 'LOCAL_DETERMINISTIC',
    "status" varchar(32) NOT NULL DEFAULT 'RUNNING', "input_fingerprint" char(64) NOT NULL,
    "result_json" text, "error_message" varchar(1000) DEFAULT '', "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_ai_review_finding" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "run_id" bigint NOT NULL, "contract_id" bigint NOT NULL, "revision_id" bigint NOT NULL,
    "finding_type" varchar(64) NOT NULL, "severity" varchar(16) NOT NULL DEFAULT 'INFO',
    "title" varchar(255) NOT NULL, "detail" varchar(4000) DEFAULT '', "locator_json" text,
    "resolution" varchar(32) DEFAULT NULL, "resolved_by" bigint DEFAULT NULL, "resolved_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_party_import_job" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "job_key" varchar(128) NOT NULL, "file_name" varchar(255) NOT NULL,
    "status" varchar(32) NOT NULL DEFAULT 'VALIDATING', "mapping_json" text,
    "total_count" int NOT NULL DEFAULT 0, "success_count" int NOT NULL DEFAULT 0,
    "failed_count" int NOT NULL DEFAULT 0, "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_party_import_item" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "job_id" bigint NOT NULL, "row_no" int NOT NULL, "source_json" text NOT NULL,
    "duplicate_party_id" bigint DEFAULT NULL, "status" varchar(32) NOT NULL DEFAULT 'PENDING',
    "error_message" varchar(1000) DEFAULT '', "party_id" bigint DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_integration_run" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "integration_type" varchar(64) NOT NULL, "run_key" varchar(128) NOT NULL,
    "mode" varchar(32) NOT NULL DEFAULT 'SANDBOX', "status" varchar(32) NOT NULL DEFAULT 'RUNNING',
    "summary_json" text, "error_message" varchar(1000) DEFAULT '', "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_integration_delivery" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "delivery_key" varchar(160) NOT NULL, "channel" varchar(32) NOT NULL DEFAULT 'DINGTALK',
    "message_type" varchar(32) NOT NULL, "recipient_user_id" bigint NOT NULL,
    "contract_id" bigint DEFAULT NULL, "task_id" varchar(64) DEFAULT NULL,
    "deep_link_path" varchar(500) DEFAULT '', "status" varchar(32) NOT NULL DEFAULT 'PENDING',
    "attempt_count" int NOT NULL DEFAULT 0, "next_retry_time" timestamp DEFAULT NULL,
    "last_error" varchar(1000) DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_handover_case" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "source_user_id" bigint NOT NULL, "target_user_id" bigint DEFAULT NULL,
    "status" varchar(32) NOT NULL DEFAULT 'OPEN', "reason" varchar(1000) DEFAULT '',
    "handled_by" bigint DEFAULT NULL, "finished_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_handover_item" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "case_id" bigint NOT NULL, "item_type" varchar(32) NOT NULL,
    "contract_id" bigint DEFAULT NULL, "task_id" varchar(64) DEFAULT NULL,
    "original_assignee" bigint NOT NULL, "target_user_id" bigint DEFAULT NULL,
    "status" varchar(32) NOT NULL DEFAULT 'PENDING', "result_message" varchar(1000) DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "clm_approval_edit_request" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "task_id" varchar(64) NOT NULL, "approval_case_id" bigint NOT NULL,
    "contract_id" bigint NOT NULL, "base_revision_id" bigint NOT NULL,
    "result_revision_id" bigint NOT NULL, "result_approval_case_id" bigint DEFAULT NULL,
    "request_id" varchar(128) NOT NULL, "change_level" varchar(32) NOT NULL,
    "reason" varchar(1000) NOT NULL DEFAULT '',
    "creator" varchar(64) DEFAULT '', "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '', "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE, "tenant_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id")
);
